package com.example.lifecoach.worker
import android.app.*;import android.content.*;import com.example.lifecoach.data.Schedule;import java.util.*
object AlarmScheduler { fun scheduleNext(c:Context){val am=c.getSystemService(AlarmManager::class.java);val now=System.currentTimeMillis();val cal=Calendar.getInstance();var found:Pair<Long,String>?=null;for(d in 0..1){for(s in Schedule.work){val x=Calendar.getInstance().apply{timeInMillis=now;add(Calendar.DAY_OF_YEAR,d);set(Calendar.HOUR_OF_DAY,s.hour);set(Calendar.MINUTE,s.minute);set(Calendar.SECOND,0);set(Calendar.MILLISECOND,0)};if(x.timeInMillis>now&&(found==null||x.timeInMillis<found!!.first))found=x.timeInMillis to s.question}};found?.let{val pi=PendingIntent.getBroadcast(c,42,Intent(c,AlarmReceiver::class.java).putExtra("slot",it.second),PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE);if(Build.VERSION.SDK_INT<31||am.canScheduleExactAlarms())am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,it.first,pi)}}}
